parameters.jsCode:
const raw = JSON.parse($json.content.parts[0].text);

const validatedData = {
  supplier_name: raw.supplier_name || "",
  invoice_number: raw.invoice_number || "",
  invoice_date: raw.invoice_date || "",
  tax_amount: Number(raw.tax_amount || 0),
  total_amount: Number(raw.total_amount || 0),
  currency: raw.currency || "INR",
  line_items: raw.line_items || [],
  validation_status: "valid",
  missing_fields: []
};

// Required field validation
if (!validatedData.invoice_number) {
  validatedData.missing_fields.push("invoice_number");
}

if (!validatedData.supplier_name) {
  validatedData.missing_fields.push("supplier_name");
}

if (!validatedData.total_amount) {
  validatedData.missing_fields.push("total_amount");
}

// Set validation status
if (validatedData.missing_fields.length > 0) {
  validatedData.validation_status = "manual_review";
}

return [{ json: validatedData }];

